INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7801, '2 Samuel 12:28', '2 Samuel', 12, 28, '&nbsp;اوس خپل پاتې لښکر راغونډ کړه، په ښار حمله وکړه او د خپل ځان دپاره يې ونيسه. زۀ دا نۀ غواړم چې د دې قبضه کول زما په نوم ياديږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7802, '2 Samuel 12:29', '2 Samuel', 12, 29, '&nbsp;نو داؤد خپل لښکر راغونډ کړو، ربه ته لاړو، حمله يې پرې وکړه او فتح يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7803, '2 Samuel 12:30', '2 Samuel', 12, 30, '&nbsp;داؤد د هغوئ د بُت مولک د سر نه د سرو زرو تاج واخستو چې تقريباً پينځۀ دېرش کلو وو او يو قيمتى کاڼے هم په کښې وو او دا يې په خپل تاج کښې ولګولو. هغۀ د ښار نه ډېر مالِ غنيمت هم يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7804, '2 Samuel 12:31', '2 Samuel', 12, 31, '&nbsp;او د دې ځائ د خلقو نه يې په ارو، د اوسپنې په رمبو او د اوسپنې په تبرُونو کار اخستو او دې ته يې مجبور کړل چې خَښتې جوړوى. هغۀ د عمون د نورو ټولو ښارونو په خلقو هم دغه شان کار کولو. بيا هغه او د هغۀ سړى يروشلم ته راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7805, '2 Samuel 13:1', '2 Samuel', 13, 1, '&nbsp;د داؤد د زوئ ابى‌سلوم يوه ښائسته ناوادۀ شوې خور وه چې نوم يې تامار وو. د داؤد يو بل زوئ امنون په هغې باندې مئين شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7806, '2 Samuel 13:2', '2 Samuel', 13, 2, '&nbsp;هغۀ ورسره دومره مينه کوله چې هغې پسې بيمار شو، هغې د سړو سره تعلق نۀ ساتلو او د هغۀ خيال نۀ راتلو چې دا پېغله به د هغۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7807, '2 Samuel 13:3', '2 Samuel', 13, 3, '&nbsp;خو د هغۀ يو چالاک دوست وو چې نوم يې يوندب وو. دا سړے د داؤد د ورور د سِمعه زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7808, '2 Samuel 13:4', '2 Samuel', 13, 4, '&nbsp;يوندب امنون ته ووئيل، ”تۀ د بادشاه زوئ يې، خو ورځ په ورځ تۀ نور هم زيات پرېشانه ښکارې، دا څۀ وجه ده؟“ هغۀ ورته په جواب کښې ووئيل، ”زۀ د خپل ناسکه ورور ابى‌سلوم په خور تامار باندې مئين يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7809, '2 Samuel 13:5', '2 Samuel', 13, 5, '&nbsp;يوندب ورته ووئيل، ”د ځان نه بيمار جوړ کړه او په کټ کښې څمله. کله چې ستا پلار مِلاوېدو له درشى نو هغۀ ته ووايه چې مِهربانى وکړه زما خور تامار ته ووايه چې راشى او ما له څۀ خوراک راکړى. زۀ غواړم چې هغه دلته زما په مخکښې زما دپاره خوراک تيار کړى او بيا يې ما له په خپل لاس راکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7810, '2 Samuel 13:6', '2 Samuel', 13, 6, '&nbsp;نو امنون بهانه وکړه چې زۀ بيمار يم او په کټ کښې څملاستو. داؤد بادشاه مِلاوېدو له ورَغلو او امنون ورته ووئيل، ”مِهربانى وکړه تامار پرېږده چې راشى او زما په مخکښې دلته يو څو روټۍ تيارې کړى او بيا يې ما له په خپل لاس راکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7811, '2 Samuel 13:7', '2 Samuel', 13, 7, '&nbsp;نو داؤد د تامار کور ته خبر ورولېږلو چې، ”د امنون کور ته لاړه شه او د هغۀ دپاره څۀ خوراک تيار کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7812, '2 Samuel 13:8', '2 Samuel', 13, 8, '&nbsp;هغه هلته لاړه او هغه يې وليدو چې ملاست وو. هغې يو څو پېړې واخستلې، جوړې يې کړې او د هغۀ په مخکښې يې هلته روټۍ پخې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7813, '2 Samuel 13:9', '2 Samuel', 13, 9, '&nbsp;او د تبخى نه يې لرې کړې چې هغه يې وخورى، خو هغۀ ونۀ خوړې. هغۀ ووئيل، ”هر يو کس بهر کړه.“ نو هغوئ ټول لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7814, '2 Samuel 13:10', '2 Samuel', 13, 10, '&nbsp;بيا هغۀ ورته ووئيل، ”روټۍ دلته ما له کټ له راوړه او ما له يې په خپل لاس راکړه.“ هغې روټۍ واخستلې او هغۀ له ورغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7815, '2 Samuel 13:11', '2 Samuel', 13, 11, '&nbsp;کله چې هغې روټۍ ورله راوړه نو هغۀ راونيوله او ورته يې ووئيل، ”راځه زما خورې، ما سره څمله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7816, '2 Samuel 13:12', '2 Samuel', 13, 12, '&nbsp;هغې ورته ووئيل، ”نه زما وروره، داسې بې‌شرمه کار ته ما مۀ مجبوروه، په کار نۀ دى چې داسې بد عمل په بنى اِسرائيلو کښې وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7817, '2 Samuel 13:13', '2 Samuel', 13, 13, '&nbsp;زۀ به بيا په خلقو کښې سر څنګه اوچتوم؟ او تۀ به په بنى اِسرائيلو کښې بېخى بې‌عزته يې. زۀ ستا مِنت کوم چې بادشاه ته ووايه او زما دا يقين دے چې هغه به مې تا له درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7818, '2 Samuel 13:14', '2 Samuel', 13, 14, '&nbsp;خو د هغې خبره يې وانۀ ورېده، او ځکه چې هغه د هغې نه تکړه وو نو قابو يې کړه او په زور يې د هغې بې‌عزتى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7819, '2 Samuel 13:15', '2 Samuel', 13, 15, '&nbsp;بيا امنون د هغې نه ډېر زيات نفرت شروع کړو، هغۀ د هغې سره د هغې نه هم زيات نفرت کولو چې څومره يې مخکښې مينه ورسره کوله. هغۀ ورته ووئيل، ”پاڅه او ورکه شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7820, '2 Samuel 13:16', '2 Samuel', 13, 16, '&nbsp;هغې ورته ووئيل، ”نه، زۀ نۀ ځم، تۀ چې ما داسې لېږې نو دا د هغې نه هم لوئ جرم دے، څۀ چې تا اوس اوس زما سره وکړل.“ خو امنون د هغې خبرې ته غوږ نۀ نيولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7821, '2 Samuel 13:17', '2 Samuel', 13, 17, '&nbsp;هغۀ خپل نوکر راوغوښتو او ورته يې ووئيل، ”دا ښځه زما د نظره لرې کړه. دا بهر وباسه او دروازه ورپسې بنده کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7822, '2 Samuel 13:18', '2 Samuel', 13, 18, '&nbsp;نوکر هغه بهر کړه او دروازه يې ورپسې بنده کړه. تامار د اوږدو لستُوڼو اوږده چُوغه اغوستې وه، چې په هغه وخت کښې د يوې پېغلې شهزادګۍ دا عام لِباس وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7823, '2 Samuel 13:19', '2 Samuel', 13, 19, '&nbsp;هغې په خپل سر ايرې واچولې، چُوغه يې وشلوله او خپل مخ يې په لاسونو پټ کړو. په چغو چغو يې ژړل او روانه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7824, '2 Samuel 13:20', '2 Samuel', 13, 20, '&nbsp;کله چې خپل ورور ابى‌سلوم هغه وليده نو تپوس يې ترې نه وکړو، ”امنون تا سره داسې غلط کار کړے دے څۀ؟ زما خورې، په دې باندې مۀ خفه کېږه. هغه ستا ناسکه ورور دے او د دې په حقله هيچا ته هم مۀ وايه.“ نو تامار د ابى‌سلوم په کور کښې يواځې او خفه اوسېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7825, '2 Samuel 13:21', '2 Samuel', 13, 21, '&nbsp;کله چې داؤد بادشاه خبر شو چې څۀ شوى وُو، نو هغه سخت غصه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7826, '2 Samuel 13:22', '2 Samuel', 13, 22, '&nbsp;او ابى‌سلوم د امنون سره دومره نفرت کولو چې هغۀ سره يې نورې خبرې هم نۀ کولې ځکه چې د هغۀ د خور تامار سره امنون په زور زنا کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7827, '2 Samuel 13:23', '2 Samuel', 13, 23, '&nbsp;دوه کاله وروستو ابى‌سلوم د اِفرائيم ښار سره نزدې په بعل حصور کښې خپلې ګډې کلولې او د بادشاه ټول زامن يې راوغوښتل چې هلته راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7828, '2 Samuel 13:24', '2 Samuel', 13, 24, '&nbsp;هغه داؤد بادشاه له لاړو او ورته يې ووئيل، ”بادشاه سلامت، زۀ خپلې ګډې کلوم. تۀ او ستا آفسران به راشئ چې ما سره په دې کښې شريک شئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7829, '2 Samuel 13:25', '2 Samuel', 13, 25, '&nbsp;بادشاه ورته وفرمائيل، ”نه، زما زويه، کۀ مونږ ټول ورشو نو دا به ستا دپاره لوئ تکليف وى.“ ابى‌سلوم ورته بيا بيا وئيل او بادشاه د هغۀ سره نۀ تلو خو هغۀ د ابى‌سلوم دپاره برکت وغوښتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7830, '2 Samuel 13:26', '2 Samuel', 13, 26, '&nbsp;خو ابى‌سلوم ورته ووئيل، ”ښه، کم از کم زما ورور امنون خو به پرېږدې کنه چې ما سره لاړ شى.“ بادشاه ترې نه تپوس وکړو، ”هغه دې ولې لاړ شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7831, '2 Samuel 13:27', '2 Samuel', 13, 27, '&nbsp;خو ابى‌سلوم بيا بيا ورته وئيل چې داؤد آخر هم امنون او خپل نور ټول زامن پرېښودل چې د ابى‌سلوم سره لاړ شى. ابى‌سلوم يوه شاهى روټۍ تياره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7832, '2 Samuel 13:28', '2 Samuel', 13, 28, '&nbsp;هغۀ خپلو نوکرانو ته ووئيل، ”ګورئ، کله چې امنون د ميو څښلو په وجه په سُور کښې شى او چې زۀ حُکم درکړم چې هغه ووژنئ نو يرېږئ مه. زۀ به په خپله د دې ذمه وارى اخلم. تکړه شئ او چې ونۀ يرېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7833, '2 Samuel 13:29', '2 Samuel', 13, 29, '&nbsp;نو نوکرانو د ابى‌سلوم په خبره عمل وکړو او امنون يې ووژلو. د داؤد باقى نور ټول زامن په خپلو قچرو باندې سوارۀ شول او وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7834, '2 Samuel 13:30', '2 Samuel', 13, 30, '&nbsp;څۀ وخت چې هغوئ خپل کور ته راروان وُو، نو داؤد ته داسې ووئيلے شول، ”ابى‌سلوم ستا ټول زامن وژلى دى، يو هم پاتې نۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7835, '2 Samuel 13:31', '2 Samuel', 13, 31, '&nbsp;بادشاه پاڅېدو، د غم نه يې خپلې جامې وشلولې او خپل ځان يې په زمکه وغورزولو. کوم نوکران چې د هغۀ سره هلته وُو نو هغوئ هم خپلې جامې وشلولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7836, '2 Samuel 13:32', '2 Samuel', 13, 32, '&nbsp;خو د داؤد د ورور سِمعه زوئ يوندب ووئيل، ”بادشاه سلامت، دا خيال مۀ کوه چې هغوئ ستا ټول زامن وژلى دى. صِرف امنون مړ دے. په کومه ورځ چې امنون د تامار سره په زور زنا وکړه نو ابى‌سلوم د هغۀ د وژلو فېصله کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7837, '2 Samuel 13:33', '2 Samuel', 13, 33, '&nbsp;نو په دې خبره يقين مۀ کوه چې ستا ټول زامن مړۀ شوى دى، صِرف امنون وژلے شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7838, '2 Samuel 13:34', '2 Samuel', 13, 34, '&nbsp;په دې دوران کښې ابى‌سلوم تښتېدلے وو. نو بيا پهره دار ډېر خلق وليدل چې د حورونايم په لاره د غرۀ نه راکوزېدل. هغه بادشاه له لاړو او چې څۀ يې ليدلى وُو د هغې نه يې خبر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7839, '2 Samuel 13:35', '2 Samuel', 13, 35, '&nbsp;يوندب داؤد ته ووئيل، ”وګورئ، هغه دى ستا زامن راروان دى څنګه چې ما درته وئيلى وُو چې هغوئ به راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7840, '2 Samuel 13:36', '2 Samuel', 13, 36, '&nbsp;چې څنګه هغۀ دا خبره ختمه کړه، نو د داؤد زامن راننوتل، هغوئ په ژړا شروع وکړه او داؤد او د هغۀ آفسرانو هم په چغو چغو وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7841, '2 Samuel 13:39', '2 Samuel', 13, 39, '&nbsp;خو کله چې داؤد د امنون د مرګ نه په آرام شو، نو د هغۀ زړۀ بيا دا غوښتل چې د ابى‌سلوم سره مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7842, '2 Samuel 14:1', '2 Samuel', 14, 1, '&nbsp;يوآب ته پته ولګېده چې د داؤد بادشاه ابى‌سلوم ډېر زيات ياديږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7843, '2 Samuel 14:2', '2 Samuel', 14, 2, '&nbsp;نو هغۀ يوه هوښياره ښځه راوغوښتله چې په تقوع کښې اوسېده. کله چې هغه راورسېده، نو هغۀ ورته ووئيل، ”داسې ښکاره کړه چې تۀ په غم غمژنه يې، د غم جامې واغونده او تېل مۀ لګوه. داسې کار کوه لکه چې يوه ښځه د ډېر وخت نه په غم غمژنه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7844, '2 Samuel 14:3', '2 Samuel', 14, 3, '&nbsp;بيا بادشاه له لاړه شه او چې زۀ درته څۀ وايم نو هغه ورته ووايه.“ نو يوآب ورته هغه څۀ وښودل چې هغې له څۀ وئيل په کار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7845, '2 Samuel 14:4', '2 Samuel', 14, 4, '&nbsp;ښځه بادشاه له ورغله، د عزت نه ورته په زمکه ټيټه شوه او ورته يې ووئيل، ”بادشاه سلامت، زما مدد وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7846, '2 Samuel 14:5', '2 Samuel', 14, 5, '&nbsp;هغۀ ترې نه تپوس وکړو، ”تا ته څۀ تکليف دے؟“ هغې ورته ووئيل، ”بادشاه سلامت، زۀ يوه غريبه کونډه يم، خاوند مې مړ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7847, '2 Samuel 14:6', '2 Samuel', 14, 6, '&nbsp;بادشاه سلامت، زما دوه زامن وُو او يوه ورځ په پټو کښې په خپلو کښې په جګړه شول، هلته هيڅ څوک هم نۀ وُو چې هغوئ يې خلاص کړى وے، نو يو هغه بل ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7848, '2 Samuel 14:7', '2 Samuel', 14, 7, '&nbsp;او اوس بادشاه سلامت، زما ټول خپلوان زما خِلاف شوى دى او ما ته وائى چې زۀ خپل زوئ هغوئ ته حواله کړم، نو چې هغوئ يې د خپل ورور په بدل ووژنى. کۀ هغوئ داسې وکړى نو زۀ به بې‌زويه پاتې شم. هغوئ به زما آخرى اُميد هم ختم کړى او زما يو زوئ به هم نۀ وى چې د هغې په وجه زما د خاوند نوم د زمکې په مخ باقى پاتې شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7849, '2 Samuel 14:8', '2 Samuel', 14, 8, '&nbsp;بادشاه ورته وفرمائيل، ”واپس کور ته لاړه شه، زۀ به دا مسئله حل کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7850, '2 Samuel 14:9', '2 Samuel', 14, 9, '&nbsp;هغې ووئيل، ”بادشاه سلامت، تۀ چې څۀ هم کوې، زۀ او زما خاندان به د هغې اِلزام اخلو، تۀ او ستا شاهى خاندان بې‌ګناه يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7851, '2 Samuel 14:10', '2 Samuel', 14, 10, '&nbsp;بادشاه ورته وفرمائيل، ”کۀ څوک تا له دهمکى درکړى نو ما له يې راوله او هغه به هيڅکله هم بيا تا له تکليف نۀ درکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7852, '2 Samuel 14:11', '2 Samuel', 14, 11, '&nbsp;هغې ورته ووئيل، ”بادشاه سلامت، مالِک خُدائ خپل خُدائ پاک ته سوال وکړه چې تۀ به هيڅ څوک نۀ پرېږدې چې زما د زوئ نه د مرګ بدل واخلى، زۀ نۀ غواړم چې نوره وينه توئ شى.“ نو داؤد ورته وئيل، ”زۀ د ژوندى مالِک خُدائ په نوم قسم کوم چې ستا د زوئ يو وېښتۀ به هم نۀ ضائع کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7853, '2 Samuel 14:12', '2 Samuel', 14, 12, '&nbsp;هغې ورته ووئيل، ”بادشاه سلامت، ما له اجازت راکړه چې يوه بله مسئله بيان کړم.“ هغۀ ورته وفرمائيل، ”ټيک ده ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7854, '2 Samuel 14:13', '2 Samuel', 14, 13, '&nbsp;هغې ورته ووئيل، ”تا د خُدائ پاک د خلقو سره دومره بد ولې کړى دى؟ تۀ خپل زوئ له اجازت نۀ ورکوې چې د جلاوطنۍ نه راواپس شى، اوس اوس چې تا څۀ ووئيل نو تا په خپله خپل ځان مجرم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7855, '2 Samuel 14:14', '2 Samuel', 14, 14, '&nbsp;مونږ به ټول مرو، مونږ په زمکه د تويو شوو اوبو په شان يُو، چې هغه بيا نۀ شى راغونډېدلے. خو خُدائ پاک د چا هلاکېدل نۀ غواړى او هغه داسې منصوبې جوړوى چې يو شړلے کس واپس ځان ته راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7856, '2 Samuel 14:15', '2 Samuel', 14, 15, '&nbsp;اوس بادشاه سلامت، زما تا سره د خبرو کولو دپاره د راتلو وجه دا ده چې خلقو زۀ يرولم، نو ما د خپل ځان سره ووئيل چې زۀ په دې اُميد تا سره خبره وکړم چې زۀ څۀ غواړم نو هغه به وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7857, '2 Samuel 14:16', '2 Samuel', 14, 16, '&nbsp;زما خيال دا وو چې تۀ به زما خبره واورې او د هغه کس نه به مې بچ کړې څوک چې زما او زما د زوئ د وژلو کوشش کوى او چې داسې مونږ د هغه مُلک نه لرې کړى چې خُدائ پاک خپلو خلقو له ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7858, '2 Samuel 14:17', '2 Samuel', 14, 17, '&nbsp;ما د خپل ځان سره ووئيل چې بادشاه سلامت، ستا خبرې دې ما له تسلى راکړى، ځکه چې بادشاه د خُدائ پاک د فرښتې په شان وى او ښۀ د بد نه جدا کوى. مالِک خُدائ ستا خُدائ پاک دې مل شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7859, '2 Samuel 14:18', '2 Samuel', 14, 18, '&nbsp;بادشاه جواب ورکړو، ”زۀ ستا نه يو تپوس کوم او تۀ به ما ته رښتيا رښتيا وائې.“ هغې جواب ورکړو، ”بادشاه سلامت، څۀ چې وئيل غواړې نو هغه ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7860, '2 Samuel 14:19', '2 Samuel', 14, 19, '&nbsp;هغۀ ترې نه تپوس وکړو، ”دا هر څۀ په تا باندې يوآب وکړل څۀ؟“ هغې ورته ووئيل، ”بادشاه سلامت، زۀ تا ته قسم خورم چې بله لاره نشته چې جواب درنۀ کړم. په حقيقت سره هغه ستا آفسر يوآب وو چې هغۀ ما ته ووئيل چې څۀ به کوم او څۀ به وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7861, '2 Samuel 14:20', '2 Samuel', 14, 20, '&nbsp;خو هغۀ دا د دې دپاره وکړل چې ستا اراده بدله شى. بادشاه سلامت، تۀ د خُدائ پاک د فرښتې په شان هوښيار يې او چې څۀ کيږى په هغې باندې پوهېږې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7862, '2 Samuel 14:21', '2 Samuel', 14, 21, '&nbsp;وروستو بادشاه يوآب ته وفرمائيل، ”تۀ چې څۀ غواړې نو ما د هغې د کولو فېصله کړې ده. لاړ شه او هغه زلمے ابى‌سلوم ولټوه او واپس يې دلته راوله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7863, '2 Samuel 14:22', '2 Samuel', 14, 22, '&nbsp;يوآب د عزت نه د داؤد په مخکښې پړمخې پرېوتلو او وې وئيل، ”بادشاه سلامت، مالِک خُدائ دې تا له برکت درکړى. اوس ما ته پته ولګېده چې تۀ زما نه خوشحاله يې، ځکه چې تا زما عرض منلے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7864, '2 Samuel 14:23', '2 Samuel', 14, 23, '&nbsp;بيا يوآب پاڅېدو او جسور ته لاړو او ابى‌سلوم يې واپس يروشلم ته راوستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7865, '2 Samuel 14:24', '2 Samuel', 14, 24, '&nbsp;خو بادشاه حُکم وکړو چې ابى‌سلوم دې په محل کښې نۀ اوسيږى. بادشاه وفرمائيل، ”زۀ د هغۀ ليدل نۀ غواړم.“ نو ابى‌سلوم په خپل کور کښې اوسېدو او د بادشاه مخې له به نۀ راتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7866, '2 Samuel 14:25', '2 Samuel', 14, 25, '&nbsp;په بنى اِسرائيلو کښې په ښائست کښې د ابى‌سلوم په شان مشهور هيڅ څوک هم نۀ وو، د سر نه تر پښو پورې په هغۀ کښې هيڅ عېب هم نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7867, '2 Samuel 14:26', '2 Samuel', 14, 26, '&nbsp;د هغۀ وېښتۀ ګڼ وُو او هغۀ به دا په کال کښې يو ځل واړۀ کول، کله به چې دا اوږدۀ او درانۀ شول. دا د بادشاه د وزن د معيار په مطابق دوه کلو درانۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7868, '2 Samuel 14:27', '2 Samuel', 14, 27, '&nbsp;د ابى‌سلوم درې زامن او يوه يې لور تامار وه چې هغه ډېره ښائسته جينۍ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7869, '2 Samuel 14:28', '2 Samuel', 14, 28, '&nbsp;ابى‌سلوم په يروشلم کښې دوه کاله اوسېدو او د بادشاه په مخکښې نۀ حاضرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7870, '2 Samuel 14:29', '2 Samuel', 14, 29, '&nbsp;بيا هغۀ يوآب راوغوښتو چې ورته ووائى چې د هغۀ دپاره بادشاه له لاړ شى، خو يوآب به نۀ راتلو. ابى‌سلوم هغه بيا راوغوښتو او يوآب بيا د راتلو نه اِنکار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7871, '2 Samuel 14:30', '2 Samuel', 14, 30, '&nbsp;نو ابى‌سلوم خپلو نوکرانو ته ووئيل، ”ګورئ، د يوآب پټے زما سره نزدې دے او اوربشې په کښې شوې دى. لاړ شئ او اور پرې ولګوئ.“ نو هغوئ لاړل او په پټى يې اور بل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7872, '2 Samuel 14:31', '2 Samuel', 14, 31, '&nbsp;يوآب د ابى‌سلوم کور ته لاړو او ورته يې ووئيل، ”ستا نوکرانو زما پټى باندې اور ولې بل کړے دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7873, '2 Samuel 14:32', '2 Samuel', 14, 32, '&nbsp;ابى‌سلوم ورته ووئيل، ”دا ځکه چې کله ما تۀ راغوښتلې نو تۀ به نۀ راتلې. ما غوښتل چې بادشاه له لاړ شې او هغۀ ته زما دپاره ووائې چې زۀ د جسور نه دلته ولې راغلم؟ ښۀ به دا وے چې زۀ هلته ايسار وے.“ او ابى‌سلوم وئيل، ”زۀ غواړم چې تۀ زما دپاره د بادشاه سره د مِلاوېدو بندوبست وکړې او کۀ زۀ په غلطه يم، نو هغه دې ما ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7874, '2 Samuel 14:33', '2 Samuel', 14, 33, '&nbsp;نو يوآب داؤد بادشاه له لاړو او چې ابى‌سلوم څۀ وئيلى وُو هغه يې ورته ووئيل. بادشاه ابى‌سلوم راوغوښتو، هغه ورله راغلو او د هغۀ په مخکښې زمکې ته ټيټ شو. نو بادشاه ابى‌سلوم ښکل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7875, '2 Samuel 15:1', '2 Samuel', 15, 1, '&nbsp;د هغې نه پس، ابى‌سلوم د ځان دپاره ګاډۍ او آسونه تيار کړل او پنځوسو محافظانو به د دې نه مخکښې منډې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7876, '2 Samuel 15:2', '2 Samuel', 15, 2, '&nbsp;هغه به وختى پاڅېدو او لا به ړو او د ښار د دروازې سره به په لاره کښې ودرېدو. کله به هم چې څوک د يوې لانجې سره هلته راغلو چې هغۀ به غوښتل چې بادشاه لانجه هواره کړى، نو ابى‌سلوم به هغه راوغوښتو او تپوس به يې ترې نه وکړو چې هغه د کوم ځائ دے. نو هغه سړى به ورته ووئيل چې زۀ د بنى اِسرائيلو د يوې قبيلې نه يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7877, '2 Samuel 15:3', '2 Samuel', 15, 3, '&nbsp;نو ابى‌سلوم به ووئيل، ”ګوره، ستا دعوىٰ په حقه ده، خو د بادشاه يو داسې سړے نشته چې ستا مسئله واورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7878, '2 Samuel 15:4', '2 Samuel', 15, 4, '&nbsp;او هغۀ به دا هم وئيل، ”دا به څومره ښۀ وے چې زۀ قاضى مقرر کړے شوے وے. کۀ بيا د چا لانجه يا دعوىٰ وے نو هغه به ما له راتلے او ما به اِنصاف ورکولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7879, '2 Samuel 15:5', '2 Samuel', 15, 5, '&nbsp;کله چې هغه سړے ورله نزدې راغلو چې د ابى‌سلوم په وړاندې ټيټ شى، نو ابى‌سلوم به ورورسېدو، هغه به يې ونيولو او ښُکل به يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7880, '2 Samuel 15:6', '2 Samuel', 15, 6, '&nbsp;ابى‌سلوم داسې د هر يو بنى اِسرائيلى سره کول چې هغه به د اِنصاف دپاره بادشاه له ورتلو، نو داسې هغۀ د بنى اِسرائيلو زړونه وګټل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7881, '2 Samuel 15:7', '2 Samuel', 15, 7, '&nbsp;څلور کاله پس ابى‌سلوم داؤد بادشاه ته ووئيل، ”بادشاه سلامت، ما له اجازت راکړه چې زۀ حبرون ته لاړ شم او چې زۀ هغه لوظ پوره کړم چې ما د مالِک خُدائ سره کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7882, '2 Samuel 15:8', '2 Samuel', 15, 8, '&nbsp;کله چې زۀ په شام کښې په جسور کښې اوسېدم، نو ما د مالِک خُدائ سره لوظ وکړو چې کۀ هغه ما واپس يروشلم ته بوځى، نو زۀ به په حبرون کښې د هغۀ عبادت وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7883, '2 Samuel 15:9', '2 Samuel', 15, 9, '&nbsp;بادشاه ورته وفرمائيل، ”په خېر لاړ شه.“ نو ابى‌سلوم حبرون ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7884, '2 Samuel 15:10', '2 Samuel', 15, 10, '&nbsp;خو هغۀ په پټه باندې د بنى اِسرائيلو ټولو قبيلو ته پېغام وړُونکى ولېږل چې ورته ووائى، ”کله چې تاسو د بيګل آواز واورئ نو په چغو ووايئ چې ابى‌سلوم په حبرون کښې بادشاه جوړ شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7885, '2 Samuel 15:11', '2 Samuel', 15, 11, '&nbsp;دوه سوه سړى د هغۀ سره د ابى‌سلوم په دعوت باندې يروشلم ته تلى وُو، هغوئ ته د دې منصوبې په حقله هيڅ پته نۀ وه او ټول په صفا زړۀ تلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7886, '2 Samuel 15:12', '2 Samuel', 15, 12, '&nbsp;کله چې ابى‌سلوم نذرانې پېش کولې نو هغۀ اخى‌تُفل جلونے هم راوغوښتو څوک چې د داؤد مشير وو، چې د خپل ښار جلوه نه راشى. د بادشاه خِلاف منصوبه مضبوطه شوه او د ابى‌سلوم کسان زياتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7887, '2 Samuel 15:13', '2 Samuel', 15, 13, '&nbsp;يو پېغام وړونکے راغلو او داؤد ته يې ووئيل، ”بنى اِسرائيليان د ابى‌سلوم وفادار دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7888, '2 Samuel 15:14', '2 Samuel', 15, 14, '&nbsp;نو داؤد خپلو ټولو آفسرانو ته وفرمائيل چې کوم د هغۀ سره په يروشلم کښې وُو، ”کۀ مونږ د ابى‌سلوم نه تښتېدل غواړُو نو چې سمدستى وتښتُو. زر شئ. ګنې هغه به زر دلته راشى، مونږ له به شکست راکړى او په ښار کښې به هر يو کس ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7889, '2 Samuel 15:15', '2 Samuel', 15, 15, '&nbsp;هغوئ جواب ورکړو، ”بادشاه سلامت، آو، تۀ چې څۀ وائې نو مونږ د هغې کولو ته تيار يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7890, '2 Samuel 15:16', '2 Samuel', 15, 16, '&nbsp;نو بادشاه د خپلې ټول خاندان او آفسرانو سره لاړو، خو هغه خپلې لس وينځې يې پرېښودلې چې د محل خيال ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7891, '2 Samuel 15:17', '2 Samuel', 15, 17, '&nbsp;کله چې بادشاه او د هغۀ ټول سړى د ښار نه تلل، نو هغوئ د لږ مزل نه پس په آخرى کور کښې ايسار شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7892, '2 Samuel 15:18', '2 Samuel', 15, 18, '&nbsp;د هغۀ ټول آفسران ورسره ولاړ وُو چې په دې کښې شاهى فوجيان د هغۀ په مخکښې تېر شول. هغه شپږ سوه فوجيان هم تېر شول چې د جات نه ورپسې راروان وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7893, '2 Samuel 15:19', '2 Samuel', 15, 19, '&nbsp;او بادشاه د هغوئ مشر اِتى ته وفرمائيل، ”تۀ مونږ سره ولې ځې؟ واپس شه او د نوى بادشاه سره ايسار شه. تۀ مسافر يې، چې د خپل مُلک نه مهاجر شوے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7894, '2 Samuel 15:20', '2 Samuel', 15, 20, '&nbsp;تۀ دلته ډېر لږ وخت اوسېدلے يې، نو زۀ تا د ځان سره ولې وګرځوم؟ ما ته په خپله هم دا پته نۀ لګى چې زۀ چرته روان يم. واپس لاړ شه او خپل وطندار د ځان سره بوځه. او مالِک خُدائ دې تا ته خپله مِهربانى او وفادارى وښائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7895, '2 Samuel 15:21', '2 Samuel', 15, 21, '&nbsp;خو اِتى ورته ووئيل، ”بادشاه سلامت، زۀ تا ته د مالِک خُدائ او ستا په سر قسم کوم چې تۀ چرته هم ځې نو زۀ به همېشه تا سره ځم، کۀ په دې کښې د مرګ خطره هم وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7896, '2 Samuel 15:22', '2 Samuel', 15, 22, '&nbsp;داؤد ورته وفرمائيل، ”ټيک ده، راځئ چې ځُو.“ نو اِتے د خپلو ټولو سړو او بال بچ سره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7897, '2 Samuel 15:23', '2 Samuel', 15, 23, '&nbsp;چې کله د داؤد ټول کسان لاړل نو خلقو په چغو چغو وژړل. بادشاه د قِدرون ولې نه واوړېدو، چې خپل سړى ورپسې وُو او هغوئ په يو ځائ د صحرا طرف ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7898, '2 Samuel 15:24', '2 Samuel', 15, 24, '&nbsp;صدوق اِمام هلته وو او ليويانو د هغۀ سره د لوظ صندوق روان کړے وو. هغوئ دا کېښودو او بيا يې تر هغې پورې اوچت نۀ کړو چې ټول خلق د ښار نه تلى نۀ وُو. ابياتار اِمام هم هلته وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7899, '2 Samuel 15:25', '2 Samuel', 15, 25, '&nbsp;بيا بادشاه صدوق ته وفرمائيل، ”د لوظ صندوق واپس ښار ته يوسه. کۀ زۀ د مالِک خُدائ په نظر کښې ښۀ ښکارم، نو يوه ورځ به مې هغه واپس دې صندوق او د هغه ځائ ليدو له راولى چرته چې دا پروت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7900, '2 Samuel 15:26', '2 Samuel', 15, 26, '&nbsp;خو کۀ هغه زما نه رضا نۀ وى نو چې د هغۀ څۀ خوښه وى نو هغه شان دې راسره وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');